&lt;li data-start=&quot;3365&quot; data-end=&quot;3476&quot;&gt;&lt;span class=&quot;TextRun SCXW2080708 BCX8&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW2080708 BCX8&quot;&gt;The freedom to pick the tools and processes that make sense for your craft.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
